#include <bits/stdc++.h>
#define MAX_SIZE 5000010
#define INFINITY 1000000000
#define INDEX(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> void input(T &x)
{
    x=0; char c=getchar(); bool negative=false;
    while(!isdigit(c)){if(c=='-') negative=true; c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48); c=getchar();}
    if(negative) x=-x;
}
int n,m,k,v1,v2,s,t;
int distance[MAX_SIZE];
bool visited[MAX_SIZE];
struct Edge
{
    int to,next,v,cost;
}edge_list[MAX_SIZE];
int head[MAX_SIZE],edge_index=1;
void add_edge(int from,int to,int val,int cost)
{
    edge_list[++edge_index]=(Edge){to,head[from],val,cost}; head[from]=edge_index;
    edge_list[++edge_index]=(Edge){from,head[to],0,-cost}; head[to]=edge_index;
}
bool bellman_ford()
{
    queue<int> q;
    for(int i=s;i<=t;++i) distance[i]=INFINITY,visited[i]=false;
    q.push(s); distance[s]=0; visited[s]=true;
    while(!q.empty())
    {
        int x=q.front(); q.pop(); visited[x]=false;
        for(int i=head[x];i;i=edge_list[i].next)
        {
            int y=edge_list[i].to,c=edge_list[i].cost;
            if(distance[y]<=distance[x]+c||!edge_list[i].v) continue;
            distance[y]=distance[x]+c;
            if(!visited[y]) {visited[y]=true; q.push(y);}
        }
    }
    return distance[t]!=INFINITY;
}
int augment(int x,int flow_limit)
{
    if(x==t) return flow_limit;
    visited[x]=true;
    int flow_res=flow_limit;
    for(int i=head[x];i;i=edge_list[i].next)
    {
        int y=edge_list[i].to,v=edge_list[i].v;
        if(distance[y]!=distance[x]+edge_list[i].cost||!v||visited[y]) continue;
        if(int flow=augment(y,min(flow_res,v)))
        {
            flow_res-=flow;
            edge_list[i].v-=flow;
            edge_list[i^1].v+=flow;
            if(!flow_res) break;
        }
    }
    return flow_limit-flow_res;
}
int min_cost_max_flow()
{
    int total_flow=0, flow;
    while(bellman_ford())
        while(flow=augment(s,INFINITY))
            total_flow+=flow*distance[t];
    return total_flow;
}
int main()
{
    input(n); input(m); input(k); input(v1); input(v2);
    t=INDEX(n,110)+1;
    for(int i=2;i<=110;++i) add_edge(INDEX(1,i),t,INFINITY,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            add_edge(INDEX(i,j),INDEX(i,j+1),INFINITY,v1);
    for(int i=1,x;i<=k;++i) {input(x); add_edge(s,INDEX(x,1),1,0);}
    for(int i=1;i<=m;++i)
    {
        int x,y;
        input(x); input(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                add_edge(INDEX(x,j),INDEX(y,j+1),1,v2*(2*l-1)+v1),
                add_edge(INDEX(y,j),INDEX(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",min_cost_max_flow());
    return 0;
}
